class Solution {
public:
    vector<int> sortEvenOdd(vector<int>& nums) {
        vector<int> even, odd;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (i % 2 == 0) even.push_back(nums[i]);
            else odd.push_back(nums[i]);
        }
        sort(even.begin(), even.end());
        sort(odd.rbegin(), odd.rend());
        vector<int> res(nums.size());
        for (int i = 0; i < (int)even.size(); i++) res[2 * i] = even[i];
        for (int i = 0; i < (int)odd.size(); i++) res[2 * i + 1] = odd[i];
        return res;
    }
};

class Solution {
    public int[] sortEvenOdd(int[] nums) {
        List<Integer> even = new ArrayList<>();
        List<Integer> odd = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            if (i % 2 == 0) even.add(nums[i]);
            else odd.add(nums[i]);
        }
        Collections.sort(even);
        odd.sort(Collections.reverseOrder());
        int[] res = new int[nums.length];
        for (int i = 0; i < even.size(); i++) res[2 * i] = even.get(i);
        for (int i = 0; i < odd.size(); i++) res[2 * i + 1] = odd.get(i);
        return res;
    }
}

var sortEvenOdd = function(nums) {
    const even = [], odd = [];
    for (let i = 0; i < nums.length; i++) {
        if (i % 2 === 0) even.push(nums[i]);
        else odd.push(nums[i]);
    }
    even.sort((a, b) => a - b);
    odd.sort((a, b) => b - a);
    const res = new Array(nums.length);
    for (let i = 0; i < even.length; i++) res[2 * i] = even[i];
    for (let i = 0; i < odd.length; i++) res[2 * i + 1] = odd[i];
    return res;
};
